SELECT customers.segment, ROUND(STDDEV(transactions.amount), 2) stddev_amount, SUM(CASE WHEN transactions.txn_type = 'DEBIT' THEN 1 ELSE 0 END) debit_count FROM transactions LEFT JOIN accounts ON accounts.id = transactions.account_id LEFT JOIN customers ON accounts.customer_id = customers.id WHERE MONTH(accounts.opened_date) IN (3, 6, 10) GROUP BY customers.segment HAVING SUM(CASE WHEN transactions.txn_type = 'DEBIT' THEN 1 ELSE 0 END) > 76 ORDER BY segment ASC;
